        body=parts[i+1]
        blocks=re.findall(r'List\.of\((ErrorCode\.[^)]*)\)', body)
        doc[parts[i]]=re.findall(r'ErrorCode\.([A-Z_]+)', blocks[-1]) if blocks else []
    return doc
